#include <functional>
#include <string>
#include <vector>

class Guard
{
public:
    explicit Guard(std::function<bool()> save) : m_save{ std::move(save) } {}

    void setDirty(bool dirty) { m_dirty = dirty; }

    void request(const std::string& action)
    {
        if (!m_dirty) { m_done.push_back(action); return; }
        m_pending = action;
        m_open = true;
    }

    bool dialogOpen() const { return m_open; }

    void answer(const std::string& choice)
    {
        if (!m_open) return;
        if (choice == "save")
        {
            if (!m_save || !m_save()) return;          // failed: stay open
            m_dirty = false;
            m_done.push_back(m_pending);
        }
        else if (choice == "discard")
        {
            m_dirty = false;
            m_done.push_back(m_pending);
        }
        else if (choice != "cancel") return;
        m_pending.clear();
        m_open = false;
    }

    std::vector<std::string> done() const { return m_done; }

private:
    std::function<bool()> m_save;
    bool m_dirty{ false };
    bool m_open{ false };
    std::string m_pending;
    std::vector<std::string> m_done;
};

unitTests:
using Done = std::vector<std::string>;
TEST("clean: no dialog") { Guard g{ [] { return true; } }; g.request("quit"); CHECK(!g.dialogOpen()); CHECK_EQ(g.done(), (Done{ "quit" })); }
TEST("dirty: save then go") { int saves = 0; Guard g{ [&] { ++saves; return true; } }; g.setDirty(true); g.request("new"); CHECK(g.dialogOpen()); CHECK(g.done().empty()); g.answer("save"); CHECK(!g.dialogOpen()); CHECK_EQ(saves, 1); CHECK_EQ(g.done(), (Done{ "new" })); g.request("open"); CHECK_EQ(g.done(), (Done{ "new", "open" })); }
TEST("failed save stays open") { bool ok = false; Guard g{ [&] { return ok; } }; g.setDirty(true); g.request("quit"); g.answer("save"); CHECK(g.dialogOpen()); CHECK(g.done().empty()); ok = true; g.answer("save"); CHECK_EQ(g.done(), (Done{ "quit" })); }
TEST("discard") { Guard g{ [] { return true; } }; g.setDirty(true); g.request("open"); g.answer("discard"); CHECK(!g.dialogOpen()); CHECK_EQ(g.done(), (Done{ "open" })); }
TEST("cancel keeps it dirty") { Guard g{ [] { return true; } }; g.setDirty(true); g.request("quit"); g.answer("cancel"); CHECK(!g.dialogOpen()); CHECK(g.done().empty()); g.request("new"); CHECK(g.dialogOpen()); }
TEST("a new request replaces the pending one") { Guard g{ [] { return true; } }; g.setDirty(true); g.request("new"); g.request("quit"); g.answer("discard"); CHECK_EQ(g.done(), (Done{ "quit" })); }
TEST("answers without a dialog are ignored") { Guard g{ [] { return true; } }; g.answer("save"); g.answer("discard"); CHECK(g.done().empty()); }

